package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class ContactStudyTest {
 @Test public void frozenSourcesAndCandidateAreOriginal() throws Exception {Path repo=Path.of("").toAbsolutePath();while(repo!=null&&!Files.exists(repo.resolve("docs/CONTACT_033_FROZEN_CONTRACT.json")))repo=repo.getParent();assertNotNull(repo);var contract=new JSONObject(Files.readString(repo.resolve("docs/CONTACT_033_FROZEN_CONTRACT.json")));assertEquals(contract.getString("suiteSha256"),MapDefinition.sha(Files.readString(repo.resolve("workspace-engine/src/main/resources/contact-study033.json")).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8)));for(Object raw:contract.getJSONArray("preservedSources")){var f=(JSONObject)raw;assertEquals(f.getString("path"),f.getString("sha256"),MapDefinition.sha(Files.readString(repo.resolve(f.getString("path"))).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}var lock=new JSONObject(Files.readString(repo.resolve("docs/CONTACT_033_CANDIDATE_LOCK.json")));assertEquals(lock.getString("nativeSourceSha256"),MapDefinition.sha(Files.readString(repo.resolve("workspace-engine/src/main/java/fraymus/workspace/ContactPhysics.java")).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8)));for(Object raw:ContactStudy.suite().getJSONArray("cases"))assertTrue(PushLearning.plan(ContactStudy.suite(),(JSONObject)raw,UUID.randomUUID().toString(),8).getBoolean("passed"));}
 @Test public void pairedNativeStudyUsesDifferentReservedCasesAndOriginalGates() throws Exception {var root=Files.createTempDirectory("contact033-study-");String id=UUID.randomUUID().toString();try(var store=new ContactStudyStore(root)){store.start(id,UUID.randomUUID().toString());JSONObject j=null;for(int i=0;i<24000;i++){j=store.read(id);if(!j.getString("status").equals("running"))break;Thread.sleep(10);}assertEquals(j.toString(),"completed",j.getString("status"));assertEquals(32,j.getJSONArray("trials").length());var d=store.verify(id);System.out.println("CONTACT_STUDY_033 "+d);System.out.println("CONTACT_STUDY_FOLDER_033 "+root);assertTrue(d.similar(j.getJSONObject("decision")));assertEquals(16,j.getInt("candidateFrozenAfterTrial"));assertEquals("baseline-031",store.activeProfile().getString("id"));assertThrows(IllegalStateException.class,()->store.promote(id,new JSONObject().put("passed",true)));Files.writeString(root.resolve("summary.json"),j.toString());}}
}
